const getRandomFenFromArray = (fenWinningArray: string[]): string => {
  const randomIndex = Math.floor(Math.random() * fenWinningArray.length);
  return fenWinningArray[randomIndex];
};


function getTurnFromFEN(fen: string): string {
  const turn = fen.split(' ')[1];
  return turn === 'w' ? 'white' : 'black';
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

export class Ctrl {
  auth: Auth = new Auth();
  stream?: Stream;
  page: Page = 'home';
  games = new OngoingGames();
  game?: GameCtrl;
  seek?: SeekCtrl;
  challenge?: ChallengeCtrl;
  tv?: TvCtrl;


  // New properties for the settings
  level: number = 3; // Default level
  clockLimit: number = 10; // Default clock limit (10 minutes)
  clockIncrement: number = 0; // Default clock increment

  constructor(readonly redraw: () => void) {}

  openHome = async () => {
    this.page = 'home';
    if (this.auth.me) {
      await this.stream?.close();
      this.games.empty();
      this.stream = await this.auth.openStream('/api/stream/event', {}, msg => {
        switch (msg.type) {
          case 'gameStart':
            this.games.onStart(msg.game);
            break;
          case 'gameFinish':
            this.games.onFinish(msg.game);
            break;
          default:
            console.warn(`Unprocessed message of type ${msg.type}`, msg);
        }
        this.redraw();
      });
    }
    this.redraw();
  };

  openGame = async (id: string) => {
    this.page = 'game';
    this.game = undefined;
    this.redraw();
    this.game = await GameCtrl.open(this, id);
    this.redraw();
  };

  // playAi = async () => {
  //   this.game = undefined;
  //   this.page = 'game';
  //   this.redraw();
  //
  //   await this.auth.fetchBody('/api/challenge/ai', {
  //     method: 'post',
  //     body: formData({
  //       level: this.level.toString(),
  //       'clock.limit': this.clockLimit.toString(),
  //       'clock.increment': this.clockIncrement.toString()
  //     }),
  //   });
  // };




  playAiFromWinningPos = async () => {
    this.level = clamp(this.level, 1, 8);
    this.clockLimit = clamp(this.clockLimit, 1, 180);
    this.clockIncrement = clamp(this.clockIncrement, 0, 60);

    this.game = undefined;
    this.page = 'game';
    this.redraw();

    try {
      console.log('Making API call to /api/challenge/ai with the following data:');
      console.log({
        level: this.level.toString(),
        'clock.limit': this.clockLimit.toString(),
        'clock.increment': this.clockIncrement.toString(),
      });

      const fen = getRandomFenFromArray(fenWinningArray);
      const turn = getTurnFromFEN(fen);

      const response = await this.auth.fetchBody('/api/challenge/ai', {
        method: 'post',
        body: formData({
          level: this.level,
          'clock.limit': this.clockLimit*60,
          'clock.increment': this.clockIncrement,
          fen: fen,
          color: turn
        }),
      });

      // Log the response
      console.log('API Response:', response);

    } catch (error) {
      console.error('Error occurred during API call:', error);
    }
  };

  playAiFromEqualPos = async () => {
    this.level = clamp(this.level, 1, 8);
    this.clockLimit = clamp(this.clockLimit, 1, 180);
    this.clockIncrement = clamp(this.clockIncrement, 0, 60);

    this.game = undefined;
    this.page = 'game';
    this.redraw();

    try {
      console.log('Making API call to /api/challenge/ai with the following data:');
      console.log({
        level: this.level.toString(),
        'clock.limit': this.clockLimit.toString(),
        'clock.increment': this.clockIncrement.toString(),
      });

      const fen = getRandomFenFromArray(fenEqualArray);
      const turn = getTurnFromFEN(fen);

      const response = await this.auth.fetchBody('/api/challenge/ai', {
        method: 'post',
        body: formData({
          level: this.level,
          'clock.limit': this.clockLimit*60,
          'clock.increment': this.clockIncrement,
          fen: fen,
          color: turn
        }),
      });

      console.log('API Response:', response);

    } catch (error) {
      console.error('Error occurred during API call:', error);
    }
  };


  playPool = async (minutes: number, increment: number) => {
    this.seek = await SeekCtrl.make(
      {
        rated: true,
        time: minutes,
        increment,
      },
      this
    );
    this.page = 'seek';
    this.redraw();
  };

  playMaia = async (minutes: number, increment: number) => {
    this.challenge = await ChallengeCtrl.make(
      {
        username: 'maia1',
        rated: false,
        'clock.limit': minutes * 60,
        'clock.increment': increment,
      },
      this
    );
    this.page = 'challenge';
    this.redraw();
  };

  watchTv = async () => {
    this.page = 'tv';
    this.redraw();
    this.tv = await TvCtrl.open(this);
    this.redraw();
  };
}
